onClick:
{{ (() => {
  try {
    const selected = appsmith.store.selected_vendor_group || {};

    const fileUrl = String(
      selected.rfqPath ||
      selected.RFQ_PATH ||
      selected.downloadUrl ||
      selected.RFQ_DOWNLOAD_URL ||
      selected.previewUrl ||
      selected.preview_url ||
      ""
    ).trim();

    if (!fileUrl) {
      showAlert(
        "The RFQ document is not available for the selected group yet.",
        "warning"
      );
      return false;
    }

    if (!/^https:\/\//i.test(fileUrl)) {
      showAlert("The stored RFQ path is not a valid HTTPS URL.", "error");
      return false;
    }

    const parsedUrl = new URL(fileUrl);

    if (!/\.sharepoint\.com$/i.test(parsedUrl.hostname)) {
      showAlert("The stored RFQ path is not a SharePoint Online URL.", "error");
      return false;
    }

    if (/\/_layouts\/15\/download\.aspx$/i.test(parsedUrl.pathname)) {
      navigateTo(fileUrl, {}, "SAME_WINDOW");
      return true;
    }

    const normalizedPath = parsedUrl.pathname.replace(
      /^\/:[^/]+:\/r\//i,
      "/"
    );

    const siteMatch = normalizedPath.match(
      /^\/(?:sites|teams|personal)\/[^/]+/i
    );

    if (!siteMatch) {
      showAlert(
        "The SharePoint site could not be identified from the stored RFQ path.",
        "error"
      );
      return false;
    }

    const siteUrl = parsedUrl.origin + siteMatch[0];

    const sourceDoc =
      parsedUrl.searchParams.get("sourcedoc") ||
      parsedUrl.searchParams.get("UniqueId");

    let downloadUrl = "";

    if (sourceDoc) {
      const uniqueId = String(sourceDoc)
        .replace(/[{}]/g, "")
        .trim();

      if (!uniqueId) {
        showAlert(
          "The SharePoint document identifier is missing from the RFQ path.",
          "error"
        );
        return false;
      }

      downloadUrl =
        siteUrl +
        "/_layouts/15/download.aspx?UniqueId=" +
        encodeURIComponent(uniqueId);
    } else {
      if (/\/_layouts\/15\/Doc\.aspx$/i.test(normalizedPath)) {
        showAlert(
          "The SharePoint preview URL does not contain the sourcedoc identifier.",
          "error"
        );
        return false;
      }

      const cleanFileUrl = parsedUrl.origin + normalizedPath;

      downloadUrl =
        siteUrl +
        "/_layouts/15/download.aspx?SourceUrl=" +
        encodeURIComponent(cleanFileUrl);
    }

    navigateTo(downloadUrl, {}, "SAME_WINDOW");
    return true;
  } catch (error) {
    showAlert(
      "Unable to download the RFQ document: " +
        (error?.message || String(error)),
      "error"
    );
    return false;
  }
})() }}
